-- State transitions declared for ImpersonationSession: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.impersonation_sessions_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'ended'), ('active', 'expired'), ('active', 'terminated'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: impersonation_sessions.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_impersonation_sessions__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS impersonation_sessions_status_transition_check ON sapiens.impersonation_sessions;
CREATE TRIGGER impersonation_sessions_status_transition_check
    BEFORE UPDATE OF "status" ON sapiens.impersonation_sessions
    FOR EACH ROW EXECUTE FUNCTION sapiens.impersonation_sessions_status_transition_check();
